fn clip(a: Vec<i8>, min: i8, max: i8) -> Vec<i8> {
    // The caller guarantees that `min < max`; if that invariant is violated,
    // `clamp` will panic.
    a.into_iter()
     .map(|x| x.clamp(min, max))
     .collect()
}

